package com.recipechecklist;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * What was in the bank the last time we saw it.
 * <p>
 * The client can only read the bank while it is open, and drops the container
 * at other times - so counting straight from it means bank totals collapse to
 * zero the moment anything else changes your inventory, such as picking up
 * loot. Keeping our own snapshot, and writing it to disk per account, is how
 * the other bank-aware plugins do it and is what makes the counts survive a
 * logout.
 * <p>
 * The map is only ever replaced, never mutated in place, so the client thread
 * can read it while the background thread that saves it is running.
 */
@Slf4j
class BankMemory
{
	private static final Type MAP_TYPE = new TypeToken<Map<Integer, Integer>>()
	{
	}.getType();

	private final Gson gson;
	private final File directory;

	private volatile Map<Integer, Integer> items = Collections.emptyMap();
	private long accountHash = -1;
	private volatile boolean dirty;

	BankMemory(Gson gson)
	{
		this.gson = gson;
		this.directory = new File(RuneLite.RUNELITE_DIR, "recipe-checklist");
	}

	int count(int itemId)
	{
		return items.getOrDefault(itemId, 0);
	}

	/** Replace the snapshot with a freshly read bank. */
	void remember(Map<Integer, Integer> contents)
	{
		if (items.equals(contents))
		{
			return;
		}

		items = Collections.unmodifiableMap(new HashMap<>(contents));
		dirty = true;
	}

	/**
	 * Switch to an account's saved bank. Blocking IO - call off the client thread.
	 */
	synchronized void load(long accountHash)
	{
		if (this.accountHash == accountHash)
		{
			return;
		}

		flush();
		this.accountHash = accountHash;
		items = Collections.emptyMap();
		dirty = false;

		final File file = fileFor(accountHash);
		if (file == null)
		{
			return;
		}

		try (Reader reader = new InputStreamReader(Files.newInputStream(file.toPath()), StandardCharsets.UTF_8))
		{
			final Map<Integer, Integer> saved = gson.fromJson(reader, MAP_TYPE);
			if (saved != null)
			{
				items = Collections.unmodifiableMap(saved);
				log.debug("Restored {} banked item types", saved.size());
			}
		}
		catch (NoSuchFileException e)
		{
			// First time we have seen this account.
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read saved bank contents", e);
		}
	}

	/**
	 * Write the snapshot out if it has changed. Blocking IO - call off the
	 * client thread.
	 */
	synchronized void flush()
	{
		final File file = fileFor(accountHash);
		if (!dirty || file == null)
		{
			return;
		}

		final Map<Integer, Integer> snapshot = items;
		try
		{
			Files.createDirectories(directory.toPath());
			try (Writer writer = new OutputStreamWriter(
				Files.newOutputStream(file.toPath()), StandardCharsets.UTF_8))
			{
				gson.toJson(snapshot, MAP_TYPE, writer);
			}
			dirty = false;
			log.debug("Saved {} banked item types", snapshot.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not save bank contents", e);
		}
	}

	/** Null while logged out, when there is no account to file the bank under. */
	private File fileFor(long accountHash)
	{
		return accountHash == -1 ? null : new File(directory, "bank-" + accountHash + ".json");
	}
}

package com.recipechecklist;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * One thing on the checklist, together with anything added to satisfy it.
 * <p>
 * Goals form a tree. Clicking a material inside a goal adds that material's
 * recipe as a child of that goal, so two separate goals both needing oak planks
 * each keep their own plank entry at their own amount rather than sharing one.
 * A child belongs to its parent alone: folding or removing a goal takes its
 * whole subtree with it.
 */
class Goal
{
	private static final String SEPARATOR = "\t";

	final String name;
	int amount;
	boolean collapsed;

	private final List<Goal> children = new ArrayList<>();
	private Goal parent;

	Goal(String name, int amount)
	{
		this(name, amount, false);
	}

	private Goal(String name, int amount, boolean collapsed)
	{
		this.name = name;
		this.amount = Math.max(1, amount);
		this.collapsed = collapsed;
	}

	List<Goal> children()
	{
		return children;
	}

	void addChild(Goal child)
	{
		child.parent = this;
		children.add(child);
	}

	/** The child covering a recipe, or null if this goal has none yet. */
	Goal childNamed(String recipeName)
	{
		for (Goal child : children)
		{
			if (child.name.equals(recipeName))
			{
				return child;
			}
		}
		return null;
	}

	/** Detach from wherever this goal lives, taking its children with it. */
	void removeFrom(List<Goal> roots)
	{
		if (parent == null)
		{
			roots.remove(this);
		}
		else
		{
			parent.children.remove(this);
		}
	}

	/**
	 * Depth-first, one line per goal: {@code depth, amount, collapsed, name}.
	 * <p>
	 * Depth is what rebuilds the tree on the way back in, and a flat text form
	 * keeps this readable in the config file.
	 */
	static String serialize(List<Goal> roots)
	{
		StringBuilder sb = new StringBuilder();
		for (Goal root : roots)
		{
			append(sb, root, 0);
		}
		return sb.toString();
	}

	private static void append(StringBuilder sb, Goal goal, int depth)
	{
		if (sb.length() > 0)
		{
			sb.append('\n');
		}

		sb.append(depth).append(SEPARATOR)
			.append(goal.amount).append(SEPARATOR)
			.append(goal.collapsed ? '1' : '0').append(SEPARATOR)
			.append(goal.name);

		for (Goal child : goal.children)
		{
			append(sb, child, depth + 1);
		}
	}

	/**
	 * Rebuild the tree. Also reads the two older flat formats, so an existing
	 * checklist survives the upgrade instead of silently emptying.
	 */
	static List<Goal> parse(String serialized)
	{
		final List<Goal> roots = new ArrayList<>();
		if (serialized == null || serialized.isEmpty())
		{
			return roots;
		}

		final Deque<Goal> ancestors = new ArrayDeque<>();
		for (String line : serialized.split("\n"))
		{
			if (line.isEmpty())
			{
				continue;
			}

			final String[] parts = line.split(SEPARATOR);
			final Goal goal = read(parts);
			if (goal == null)
			{
				continue;
			}

			// Anything deeper than the line above it is that line's child; a
			// malformed depth just clamps rather than losing the goal.
			final int depth = parts.length >= 4 ? number(parts[0], 0) : 0;
			while (ancestors.size() > depth)
			{
				ancestors.pop();
			}

			if (ancestors.isEmpty())
			{
				roots.add(goal);
			}
			else
			{
				ancestors.peek().addChild(goal);
			}
			ancestors.push(goal);
		}

		return roots;
	}

	private static Goal read(String[] parts)
	{
		switch (parts.length)
		{
			// depth, amount, collapsed, name
			case 4:
				return new Goal(parts[3], number(parts[1], 1), "1".equals(parts[2]));
			// amount, collapsed, name
			case 3:
				return new Goal(parts[2], number(parts[0], 1), "1".equals(parts[1]));
			// amount, name
			case 2:
				return new Goal(parts[1], number(parts[0], 1), false);
			default:
				return null;
		}
	}

	private static int number(String value, int fallback)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.recipechecklist;

/** What you own of one item, and where it is. */
class ItemCount
{
	final int inventory;
	final int bank;
	final String name;

	ItemCount(int inventory, int bank, String name)
	{
		this.inventory = inventory;
		this.bank = bank;
		this.name = name;
	}

	int total()
	{
		return inventory + bank;
	}
}

package com.recipechecklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Recipe
{
	public String name;
	public int productId;
	public List<Ingredient> ingredients;

	/** How many of the product one craft yields - a bronze bar makes 15 nails. Absent means 1. */
	public int makes;

	/**
	 * What to show as this recipe's icon. Things you build rather than hold -
	 * a landing site, a POH bank chest - have no product item, so borrow the
	 * first material's icon instead of showing a blank.
	 */
	int iconItemId()
	{
		if (productId > 0)
		{
			return productId;
		}
		return ingredients == null || ingredients.isEmpty() ? 0 : ingredients.get(0).itemId;
	}

	/** Never zero, so callers can divide by it. */
	int batchSize()
	{
		return Math.max(1, makes);
	}

	/** Crafts needed to end up with {@code wanted} of the product. */
	int batchesFor(int wanted)
	{
		final int batch = batchSize();
		return (wanted + batch - 1) / batch;
	}

	public static class Ingredient
	{
		public int itemId;
		public int quantity;

		/**
		 * Other item ids that count as this material - a watered seedling is the
		 * same thing as an unwatered one as far as a checklist cares. Usually absent.
		 */
		public List<Integer> same;

		/** The material, plus anything interchangeable with it. */
		List<Integer> allIds()
		{
			if (same == null || same.isEmpty())
			{
				return Collections.singletonList(itemId);
			}

			List<Integer> ids = new ArrayList<>(same.size() + 1);
			ids.add(itemId);
			ids.addAll(same);
			return ids;
		}
	}
}

package com.recipechecklist;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import lombok.extern.slf4j.Slf4j;

/**
 * Every recipe the OSRS Wiki knows about, generated into recipes.json by
 * tools/generate_recipes.py. Around 4,000 entries, so lookups are indexed and
 * the search is capped rather than listing everything.
 */
@Slf4j
class RecipeBook
{
	private final Map<String, Recipe> byName = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	private final Map<Integer, List<Recipe>> byProductId = new HashMap<>();

	RecipeBook(Gson gson)
	{
		try (InputStream in = RecipeBook.class.getResourceAsStream("recipes.json"))
		{
			if (in == null)
			{
				log.warn("recipes.json is missing from the plugin resources");
				return;
			}

			Type listType = new TypeToken<List<Recipe>>()
			{
			}.getType();
			List<Recipe> recipes = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), listType);

			int duplicates = 0;
			if (recipes != null)
			{
				for (Recipe recipe : recipes)
				{
					if (recipe != null && recipe.name != null && recipe.ingredients != null
						&& !recipe.ingredients.isEmpty())
					{
						// Names are the lookup key, so a collision loses a recipe.
						if (byName.put(recipe.name, recipe) != null)
						{
							duplicates++;
						}
						// Scenery you build has no item behind it and so no product id.
						if (recipe.productId > 0)
						{
							byProductId.computeIfAbsent(recipe.productId, id -> new ArrayList<>()).add(recipe);
						}
					}
				}
			}

			log.debug("Loaded {} recipes", byName.size());
			if (duplicates > 0)
			{
				log.warn("{} recipes share a name and were discarded; regenerate recipes.json", duplicates);
			}
		}
		catch (Exception e)
		{
			log.error("Failed to load recipes.json", e);
		}
	}

	Recipe get(String name)
	{
		return byName.get(name);
	}

	/**
	 * Recipes for a product named without its variant - "Mahogany hull" matching
	 * the Raft, Skiff and Sloop versions. Empty when nothing starts with it.
	 */
	List<Recipe> variantsOf(String base)
	{
		final String prefix = base.toLowerCase() + " (";
		final List<Recipe> found = new ArrayList<>();
		for (Map.Entry<String, Recipe> entry : byName.entrySet())
		{
			if (entry.getKey().toLowerCase().startsWith(prefix))
			{
				found.add(entry.getValue());
			}
		}
		return found;
	}

	/**
	 * The most straightforward way to make an item, or null if it can't be made.
	 * <p>
	 * An item often has several production methods; the one needing the fewest
	 * kinds of material is the sensible default when the player has not picked
	 * one - smelting an iron bar in a furnace rather than superheating it.
	 * <p>
	 * Ties break towards the method using <i>more</i> raw material. A blast
	 * furnace halves the coal an adamantite bar needs, so defaulting to it would
	 * understate a shopping list for anyone smithing the ordinary way; being
	 * over-supplied is the harmless direction to be wrong in.
	 */
	Recipe simplestFor(int itemId)
	{
		Recipe best = null;
		for (Recipe recipe : byProductId.getOrDefault(itemId, Collections.emptyList()))
		{
			if (best == null || compare(recipe, best) < 0)
			{
				best = recipe;
			}
		}
		return best;
	}

	private static int compare(Recipe a, Recipe b)
	{
		if (a.ingredients.size() != b.ingredients.size())
		{
			return Integer.compare(a.ingredients.size(), b.ingredients.size());
		}

		int bulkA = totalQuantity(a);
		int bulkB = totalQuantity(b);
		if (bulkA != bulkB)
		{
			return Integer.compare(bulkB, bulkA);
		}

		return Integer.compare(a.name.length(), b.name.length());
	}

	private static int totalQuantity(Recipe recipe)
	{
		int total = 0;
		for (Recipe.Ingredient ingredient : recipe.ingredients)
		{
			total += ingredient.quantity;
		}
		return total;
	}

	/**
	 * The best recipe for a product named in game, or null if we have none.
	 * <p>
	 * Falls back to the product's variants, since interfaces name the thing
	 * itself: a build menu offers "Bench with lathe" where the wiki splits it
	 * into "(Total)" and "(Upgrade)". Still anchored to the whole name, so an
	 * unrecognised label matches nothing rather than something arbitrary.
	 */
	Recipe bestFor(String productName)
	{
		Recipe exact = byName.get(productName);
		if (exact != null)
		{
			return exact;
		}

		Recipe best = null;
		for (Recipe variant : variantsOf(productName))
		{
			if (best == null || compare(variant, best) < 0)
			{
				best = variant;
			}
		}
		return best != null ? best : onlyRecipeContaining(productName);
	}

	/**
	 * Last resort for labels the game words differently to the wiki: the build
	 * menu offers a "Steel framed bench" where the wiki has a "Steel framed
	 * workbench", and "Marble burners" for "Marble incense burners".
	 * <p>
	 * Every word of the label must appear in the recipe name, and the match must
	 * be the only one. Requiring uniqueness is what makes this safe - a generic
	 * label like "Upgrade" matches dozens of recipes and so matches none, which
	 * is how a hull upgrade once became a teak cape rack.
	 */
	private Recipe onlyRecipeContaining(String productName)
	{
		final String[] words = productName.toLowerCase().split("[^a-z0-9]+");

		int wordCount = 0;
		for (String word : words)
		{
			if (!word.isEmpty())
			{
				wordCount++;
			}
		}
		if (wordCount == 0)
		{
			return null;
		}

		Recipe found = null;
		for (Map.Entry<String, Recipe> entry : byName.entrySet())
		{
			final String candidate = entry.getKey().toLowerCase();

			boolean all = true;
			for (String word : words)
			{
				if (!word.isEmpty() && !candidate.contains(word))
				{
					all = false;
					break;
				}
			}

			if (all)
			{
				if (found != null)
				{
					// Ambiguous - leave it alone rather than pick one.
					return null;
				}
				found = entry.getValue();
			}
		}
		return found;
	}

	/**
	 * Case-insensitive substring search, best matches first: exact, then names
	 * starting with the query, then the rest. Shorter names win ties, which
	 * floats "Iron bar" above "Iron bar (Superheat)".
	 */
	List<String> search(String query, int limit)
	{
		final String needle = query.trim().toLowerCase();
		if (needle.isEmpty())
		{
			return Collections.emptyList();
		}

		final List<String> matches = new ArrayList<>();
		for (String name : byName.keySet())
		{
			if (name.toLowerCase().contains(needle))
			{
				matches.add(name);
			}
		}

		matches.sort((a, b) ->
		{
			int rankA = rank(a, needle);
			int rankB = rank(b, needle);
			if (rankA != rankB)
			{
				return Integer.compare(rankA, rankB);
			}
			if (a.length() != b.length())
			{
				return Integer.compare(a.length(), b.length());
			}
			return a.compareToIgnoreCase(b);
		});

		return matches.size() > limit ? matches.subList(0, limit) : matches;
	}

	private static int rank(String name, String needle)
	{
		final String lower = name.toLowerCase();
		if (lower.equals(needle))
		{
			return 0;
		}
		return lower.startsWith(needle) ? 1 : 2;
	}
}

package com.recipechecklist;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RecipeChecklistConfig.GROUP)
public interface RecipeChecklistConfig extends Config
{
	String GROUP = "recipe-checklist";

	@ConfigItem(
		keyName = "includeBank",
		name = "Count bank items",
		description = "Also count items in your bank. Bank contents are remembered between sessions, so they still"
			+ " count before you have opened a bank."
	)
	default boolean includeBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "addFromGameClicks",
		position = 1,
		name = "Add from in-game clicks",
		description = "Add a recipe to the checklist when you click it in a skill guide, the construction build menu"
			+ " or the shipwright. Only watches what you click - it does not change any menus."
	)
	default boolean addFromGameClicks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "requireShiftToAdd",
		position = 2,
		name = "Only when holding shift",
		description = "Add from in-game clicks only while shift is held, so ordinary building and browsing does not"
			+ " fill up the checklist."
	)
	default boolean requireShiftToAdd()
	{
		return true;
	}
}

