class RecipeChecklistPanel extends PluginPanel
{
	private static final int MAX_RESULTS = 12;
	private static final int MAX_AMOUNT = 100000;

	/** How far each level of sub-recipe is stepped in. */
	private static final int INDENT = 8;

	private final RecipeChecklistPlugin plugin;
	private final ItemManager itemManager;
	private final RecipeBook recipeBook;

	private final IconTextField search = new IconTextField();
	private final JSpinner quantity = new JSpinner(new SpinnerNumberModel(1, 1, MAX_AMOUNT, 1));
	private final JPanel results = new JPanel();
	private final JPanel checklist = new JPanel();

	/** Top-level goals. Sub-recipes hang off these rather than living here. */
	private final List<Goal> goals = new ArrayList<>();

	/** Every section on screen, nested ones included, for counting and redrawing. */
	private final List<GoalSection> sections = new ArrayList<>();

	private final SummarySection summary = new SummarySection();

	RecipeChecklistPanel(RecipeChecklistPlugin plugin, ItemManager itemManager, RecipeBook recipeBook)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.recipeBook = recipeBook;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		checklist.setLayout(new BoxLayout(checklist, BoxLayout.Y_AXIS));

		JPanel top = new JPanel(new BorderLayout(0, 4));
		top.add(buildSearchRow(), BorderLayout.NORTH);
		top.add(results, BorderLayout.CENTER);
		top.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

		// Stacked and pinned to the top, so sections keep their natural height
		// instead of being stretched to fill the panel.
		JPanel stack = new JPanel();
		stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
		summary.setAlignmentX(Component.LEFT_ALIGNMENT);
		checklist.setAlignmentX(Component.LEFT_ALIGNMENT);
		stack.add(summary);
		stack.add(Box.createVerticalStrut(8));
		stack.add(checklist);

		JPanel checklistWrapper = new JPanel(new BorderLayout());
		checklistWrapper.add(stack, BorderLayout.NORTH);

		add(top, BorderLayout.NORTH);
		add(checklistWrapper, BorderLayout.CENTER);
	}

	private JPanel buildSearchRow()
	{
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setToolTipText("Search recipes");
		search.setPreferredSize(new Dimension(100, 26));
		search.addClearListener(this::showResults);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				showResults();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				showResults();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				showResults();
			}
		});
		// Enter adds the best match, so you never have to reach for the mouse.
		search.addActionListener(e ->
		{
			List<String> matches = recipeBook.search(search.getText(), 1);
			if (!matches.isEmpty())
			{
				addGoal(matches.get(0), currentQuantity());
			}
		});

		quantity.setPreferredSize(new Dimension(58, 26));
		quantity.setToolTipText("How many to make");

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.add(search, BorderLayout.CENTER);
		row.add(quantity, BorderLayout.EAST);
		return row;
	}

	private int currentQuantity()
	{
		return (Integer) quantity.getValue();
	}

	// --- goals ---------------------------------------------------------------

	/** Add a top-level goal, merging with an existing one of the same name. */
	void addGoal(String name, int amount)
	{
		if (recipeBook.get(name) == null)
		{
			return;
		}

		search.setText("");
		showResults();

		for (Goal goal : goals)
		{
			if (goal.name.equals(name))
			{
				goal.amount += amount;
				syncDescendants(goal);
				persistAndRebuild();
				return;
			}
		}

		goals.add(new Goal(name, amount));
		persistAndRebuild();
	}

	/**
	 * Add a sub-recipe under the goal that needs it.
	 * <p>
	 * Deliberately not merged with a matching top-level goal: two goals that both
	 * need oak planks each keep their own entry, at their own amount, so removing
	 * one never disturbs the other's totals.
	 */
	private void addSubGoal(Goal parent, String name, int amount)
	{
		Goal existing = parent.childNamed(name);
		if (existing == null)
		{
			parent.addChild(new Goal(name, amount));
		}
		else
		{
			existing.amount = amount;
			syncDescendants(existing);
		}

		persistAndRebuild();
	}

	/**
	 * Push an amount change down the tree.
	 * <p>
	 * A sub-recipe exists to satisfy its parent, so its amount is whatever the
	 * parent now needs: asking for five spirit trees instead of one should ask
	 * for five saplings too.
	 */
	private void syncDescendants(Goal goal)
	{
		final Recipe recipe = recipeBook.get(goal.name);
		if (recipe == null || recipe.ingredients == null)
		{
			return;
		}

		final int batches = recipe.batchesFor(goal.amount);
		for (Goal child : goal.children())
		{
			final int required = requiredFor(recipe, batches, child.name);
			if (required > 0)
			{
				child.amount = required;
			}
			syncDescendants(child);
		}
	}

	/**
	 * Everything you still have to go and get, as one list.
	 * <p>
	 * A material is only listed if you have not decided to make it. Add a
	 * sub-recipe for it and it drops out, replaced by whatever that sub-recipe
	 * needs - the point being to show what to gather, not the intermediate
	 * things you will produce along the way. Quantities are summed across every
	 * goal, so two recipes both wanting oak planks give one combined figure.
	 */
	private List<Recipe.Ingredient> shoppingList()
	{
		final Map<Integer, Recipe.Ingredient> totals = new LinkedHashMap<>();
		for (Goal goal : goals)
		{
			collectMaterials(goal, totals);
		}
		return new ArrayList<>(totals.values());
	}

	private void collectMaterials(Goal goal, Map<Integer, Recipe.Ingredient> totals)
	{
		final Recipe recipe = recipeBook.get(goal.name);
		if (recipe == null || recipe.ingredients == null)
		{
			return;
		}

		final int batches = recipe.batchesFor(goal.amount);
		for (Recipe.Ingredient ingredient : recipe.ingredients)
		{
			final Goal covered = childCovering(goal, ingredient);
			if (covered != null)
			{
				// Being made rather than gathered, so its own materials count instead.
				collectMaterials(covered, totals);
				continue;
			}

			// A fresh Ingredient each time: the ones on a Recipe are shared with
			// every other goal using it and must not be written to.
			final Recipe.Ingredient total = totals.computeIfAbsent(ingredient.itemId, id ->
			{
				Recipe.Ingredient entry = new Recipe.Ingredient();
				entry.itemId = id;
				entry.same = ingredient.same;
				return entry;
			});
			total.quantity += ingredient.quantity * batches;
		}
	}

	/** The sub-goal that produces this material, if one has been added. */
	private Goal childCovering(Goal goal, Recipe.Ingredient ingredient)
	{
		for (Goal child : goal.children())
		{
			final Recipe childRecipe = recipeBook.get(child.name);
			if (childRecipe != null && ingredient.allIds().contains(childRecipe.productId))
			{
				return child;
			}
		}
		return null;
	}

	/** How many of a sub-recipe's product this recipe needs, or 0 if it needs none. */
	private int requiredFor(Recipe recipe, int batches, String childName)
	{
		final Recipe child = recipeBook.get(childName);
		if (child == null)
		{
			return 0;
		}

		for (Recipe.Ingredient ingredient : recipe.ingredients)
		{
			if (ingredient.allIds().contains(child.productId))
			{
				return Math.max(1, ingredient.quantity * batches);
			}
		}
		return 0;
	}

	private void persistAndRebuild()
	{
		plugin.persistGoals(Goal.serialize(goals));
		rebuild();
	}

	private void persist()
	{
		plugin.persistGoals(Goal.serialize(goals));
	}

	void restoreGoals(String serialized, boolean summaryCollapsed)
	{
		goals.clear();
		goals.addAll(Goal.parse(serialized));
		prune(goals);
		summary.setCollapsed(summaryCollapsed);
		rebuild();
	}

	/**
	 * Drop anything naming a recipe the current data no longer has - a
	 * regenerated recipes.json can rename entries - subtrees included, so nothing
	 * lingers invisibly in the saved list.
	 */
	private void prune(List<Goal> level)
	{
		level.removeIf(goal -> recipeBook.get(goal.name) == null);
		for (Goal goal : level)
		{
			prune(goal.children());
		}
	}

	// --- rendering -----------------------------------------------------------

	private void rebuild()
	{
		checklist.removeAll();
		sections.clear();

		for (Goal goal : goals)
		{
			GoalSection section = buildSection(goal, 0);
			if (section != null)
			{
				checklist.add(section);
				checklist.add(Box.createVerticalStrut(4));
			}
		}

		if (goals.isEmpty())
		{
			JLabel empty = new JLabel("<html>Search for something you want to make, or shift-click a recipe in a"
				+ " skill guide, build menu or shipwright in game.</html>");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			checklist.add(empty);
		}

		summary.show(shoppingList());

		checklist.revalidate();
		checklist.repaint();

		plugin.refresh();
	}

	/** Null when a saved goal names a recipe that no longer exists. */
	private GoalSection buildSection(Goal goal, int depth)
	{
		final Recipe recipe = recipeBook.get(goal.name);
		if (recipe == null)
		{
			return null;
		}

		GoalSection section = new GoalSection(goal, recipe, depth);
		sections.add(section);

		for (Goal child : goal.children())
		{
			GoalSection childSection = buildSection(child, depth + 1);
			if (childSection != null)
			{
				section.addChildSection(childSection);
			}
		}

		section.applyAmount();
		return section;
	}

	Set<Integer> trackedItemIds()
	{
		Set<Integer> ids = new HashSet<>();
		for (GoalSection section : sections)
		{
			for (IngredientRow row : section.rows)
			{
				ids.addAll(row.trackedIds());
			}
		}
		ids.addAll(summary.trackedIds());
		return ids;
	}

	/** Must run on the EDT. */
	void applyCounts(Map<Integer, ItemCount> counts)
	{
		for (GoalSection section : sections)
		{
			section.update(counts);
		}
		summary.update(counts);
	}

	private void showResults()
	{
		results.removeAll();

		for (String name : recipeBook.search(search.getText(), MAX_RESULTS))
		{
			results.add(new ResultRow(name));
		}

		results.revalidate();
		results.repaint();
	}

