	/**
	 * Right-click menu with a wiki link for an item.
	 * <p>
	 * Special:Lookup resolves an item id to its page, so this stays correct
	 * without us storing page titles alongside every recipe.
	 */
	private static JPopupMenu wikiMenu(int itemId, String name)
	{
		final String url = itemId > 0
			? "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=" + itemId
			// Scenery has no item id to look up, so search for it by name.
			: "https://oldschool.runescape.wiki/w/Special:Search?search=" + encode(name);

		JMenuItem open = new JMenuItem("Open wiki");
		open.addActionListener(e -> LinkBrowser.browse(url));

		JPopupMenu menu = new JPopupMenu();
		menu.add(open);
		return menu;
	}

	private static String encode(String value)
	{
		try
		{
			return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8.name());
		}
		catch (UnsupportedEncodingException e)
		{
			return "";
		}
	}

	/** Give a row a right-click wiki link, children included. */
	private static void attachWikiMenu(JPanel row, int itemId, String name)
	{
		row.setComponentPopupMenu(wikiMenu(itemId, name));
		for (Component child : row.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
			}
		}
	}

	/**
	 * Make a whole row clickable, not just the gaps between its labels.
	 * <p>
	 * Swing delivers a mouse event to the deepest component under the pointer and
	 * stops there - it does not bubble up to the parent the way a browser would -
	 * so a listener on the row alone never sees clicks that land on a child label.
	 * Buttons and spinners are skipped, since they have their own jobs.
	 */
	private static void makeRowClickable(JPanel row, Runnable onClick, boolean hover)
	{
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (hover)
				{
					row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Moving between two children fires an exit then an enter; only drop
				// the highlight once the pointer has actually left the row.
				if (hover && row.getMousePosition(true) == null)
				{
					row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				}
			}
		};

		row.setCursor(new Cursor(Cursor.HAND_CURSOR));
		attachDeep(row, adapter);
	}

	private static void attachDeep(Container parent, MouseAdapter adapter)
	{
		parent.addMouseListener(adapter);
		for (Component child : parent.getComponents())
		{
			if (child instanceof AbstractButton || child instanceof JSpinner)
			{
				continue;
			}
			if (child instanceof Container)
			{
				attachDeep((Container) child, adapter);
			}
			else
			{
				child.addMouseListener(adapter);
			}
		}
	}

