	/**
	 * One goal: a collapsible header, its materials, and any sub-recipes added
	 * for those materials.
	 * <p>
	 * Sub-recipes sit inside the body, so folding or removing a goal takes them
	 * with it without any extra bookkeeping.
	 */
	private class GoalSection extends JPanel
	{
		private final Goal goal;
		private final Recipe recipe;
		private final List<IngredientRow> rows = new ArrayList<>();
		private final List<GoalSection> childSections = new ArrayList<>();

		private final JPanel body = new JPanel();
		private final JPanel childHolder = new JPanel();
		private final JSpinner amount;
		private final JLabel arrow = new JLabel();
		private final JLabel summary = new JLabel();
		private final JLabel title = new JLabel();

		GoalSection(Goal goal, Recipe recipe, int depth)
		{
			this.goal = goal;
			this.recipe = recipe;
			this.amount = new JSpinner(new SpinnerNumberModel(goal.amount, 1, MAX_AMOUNT, 1));

			setLayout(new BorderLayout());
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

			body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
			body.setBackground(getBackground());
			body.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
			body.setVisible(!goal.collapsed);

			body.add(buildAmountRow());

			if (recipe.ingredients != null)
			{
				for (Recipe.Ingredient ingredient : recipe.ingredients)
				{
					IngredientRow row = new IngredientRow(goal, ingredient);
					rows.add(row);
					body.add(row);
				}
			}

			childHolder.setLayout(new BoxLayout(childHolder, BoxLayout.Y_AXIS));
			childHolder.setBackground(getBackground());
			childHolder.setBorder(BorderFactory.createEmptyBorder(4, INDENT, 0, 0));
			body.add(childHolder);

			add(buildHeader(depth), BorderLayout.NORTH);
			add(body, BorderLayout.CENTER);
		}

		void addChildSection(GoalSection child)
		{
			childSections.add(child);
			childHolder.add(child);
			childHolder.add(Box.createVerticalStrut(4));
		}

		private JPanel buildAmountRow()
		{
			amount.setPreferredSize(new Dimension(70, 22));
			amount.addChangeListener(e ->
			{
				final int value = (Integer) amount.getValue();
				if (value == goal.amount)
				{
					return;
				}

				goal.amount = value;
				applyAmount();
				persist();
				plugin.refresh();
			});

			JLabel label = new JLabel("Amount");
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(getBackground());
			row.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			row.add(label, BorderLayout.CENTER);
			row.add(amount, BorderLayout.EAST);
			return row;
		}

		/**
		 * Recompute what this goal needs, and push the new requirement down into
		 * any sub-recipes, so the whole subtree stays consistent without a rebuild.
		 */
		void applyAmount()
		{
			title.setText(goal.amount + " x " + recipe.name);

			// Keeps the spinner honest when a parent pushed a new amount down.
			// The listener no-ops on an unchanged value, so this cannot loop.
			if ((Integer) amount.getValue() != goal.amount)
			{
				amount.setValue(goal.amount);
			}

			final int batches = recipe.batchesFor(goal.amount);
			for (IngredientRow row : rows)
			{
				row.setNeeded(row.perCraft * batches);
			}

			for (GoalSection child : childSections)
			{
				final int required = requiredFor(recipe, batches, child.goal.name);
				if (required > 0 && required != child.goal.amount)
				{
					child.goal.amount = required;
				}
				child.applyAmount();
			}
		}

		private JPanel buildHeader(int depth)
		{
			arrow.setText(goal.collapsed ? "+" : "-");
			arrow.setFont(FontManager.getRunescapeBoldFont());
			arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			arrow.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 6));

			JLabel icon = new JLabel();
			itemManager.getImage(recipe.iconItemId()).addTo(icon);

			title.setFont(title.getFont().deriveFont(depth == 0 ? Font.BOLD : Font.PLAIN));
			title.setToolTipText(recipe.makes > 1
				? recipe.name + " - one craft makes " + recipe.batchSize()
				: recipe.name);
			title.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));

			summary.setHorizontalAlignment(SwingConstants.RIGHT);
			summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			JButton remove = new JButton("x");
			remove.setFocusable(false);
			remove.setPreferredSize(new Dimension(20, 20));
			remove.setToolTipText(goal.children().isEmpty()
				? "Remove from checklist"
				: "Remove this and everything added for it");
			remove.addActionListener(e ->
			{
				goal.removeFrom(goals);
				persistAndRebuild();
			});

			JPanel right = new JPanel(new BorderLayout(4, 0));
			right.setBackground(getBackground());
			right.add(summary, BorderLayout.CENTER);
			right.add(remove, BorderLayout.EAST);

			JPanel clickable = new JPanel(new BorderLayout());
			clickable.setBackground(getBackground());
			clickable.add(arrow, BorderLayout.WEST);
			clickable.add(icon, BorderLayout.CENTER);

			JPanel header = new JPanel(new BorderLayout());
			header.setBackground(getBackground());
			header.add(clickable, BorderLayout.WEST);
			header.add(title, BorderLayout.CENTER);
			header.add(right, BorderLayout.EAST);
			attachWikiMenu(header, recipe.productId, recipe.name);

			// Anywhere on the header folds the section, bar the remove button.
			makeRowClickable(header, this::toggle, false);

			return header;
		}

		private void toggle()
		{
			goal.collapsed = !goal.collapsed;
			body.setVisible(!goal.collapsed);
			arrow.setText(goal.collapsed ? "+" : "-");
			persist();
			revalidate();
			repaint();
		}

		void update(Map<Integer, ItemCount> counts)
		{
			int ready = 0;
			for (IngredientRow row : rows)
			{
				if (row.update(counts))
				{
					ready++;
				}
			}

			summary.setText(ready + "/" + rows.size());
			summary.setForeground(ready == rows.size()
				? ColorScheme.PROGRESS_COMPLETE_COLOR
				: ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	/**
	 * One material: icon, name, and have / need, coloured by where it is.
	 * <p>
	 * Shared by the per-recipe rows and the summary at the top so both read the
	 * same way and there is only one copy of the colour rules.
	 */
	private abstract class MaterialRow extends JPanel
	{
		final int itemId;
		final List<Integer> itemIds;
		final Recipe subRecipe;

		private final JLabel name = new JLabel();
		private final JLabel count = new JLabel();

		int needed;
		private int have;
		private int inInventory;
		private Color countColor = ColorScheme.PROGRESS_ERROR_COLOR;

		MaterialRow(Recipe.Ingredient ingredient)
		{
			this.itemId = ingredient.itemId;
			this.itemIds = ingredient.allIds();
			this.needed = ingredient.quantity;
			this.subRecipe = recipeBook.simplestFor(ingredient.itemId);

			setLayout(new BorderLayout(6, 0));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

			JLabel icon = new JLabel();
			// Deliberately without a quantity overlay - the stack number gets
			// clipped at this size and the count is already spelled out on the right.
			itemManager.getImage(itemId).addTo(icon);

			name.setText("Item " + itemId);

			count.setHorizontalAlignment(SwingConstants.RIGHT);

			add(icon, BorderLayout.WEST);
			add(name, BorderLayout.CENTER);
			add(count, BorderLayout.EAST);
			attachWikiMenu(this, itemId, null);

			refreshText();
		}

		void setNeeded(int needed)
		{
			this.needed = needed;
			refreshText();
		}

		/** Every id whose count this row's colour depends on. */
		Set<Integer> trackedIds()
		{
			Set<Integer> ids = new HashSet<>(itemIds);
			if (subRecipe != null && subRecipe.ingredients != null)
			{
				// Needed to tell "can't get this" from "can make this from stock".
				for (Recipe.Ingredient ingredient : subRecipe.ingredients)
				{
					ids.addAll(ingredient.allIds());
				}
			}
			return ids;
		}

		/** Returns true once you have enough of this material. */
		boolean update(Map<Integer, ItemCount> counts)
		{
			// Interchangeable ids (watered and unwatered seedlings) add up to one total.
			int inventory = 0;
			int total = 0;
			String itemName = null;

			for (int id : itemIds)
			{
				ItemCount count = counts.get(id);
				if (count == null)
				{
					continue;
				}
				inventory += count.inventory;
				total += count.total();
				if (itemName == null && id == itemId)
				{
					itemName = count.name;
				}
			}

			if (itemName != null)
			{
				name.setText(itemName);
			}

			inInventory = inventory;
			have = total;
			countColor = colorFor(counts);

			refreshText();
			return have >= needed;
		}

		/**
		 * Green in the inventory, white in the bank, yellow when you don't have it
		 * but hold everything needed to make it, red when you are short.
		 */
		private Color colorFor(Map<Integer, ItemCount> counts)
		{
			if (inInventory >= needed)
			{
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			}
			if (have >= needed)
			{
				return Color.WHITE;
			}
			if (canMakeShortfall(counts))
			{
				return ColorScheme.PROGRESS_INPROGRESS_COLOR;
			}
			return ColorScheme.PROGRESS_ERROR_COLOR;
		}

		/** Whether stock on hand covers making the amount still missing. */
		private boolean canMakeShortfall(Map<Integer, ItemCount> counts)
		{
			final int shortfall = needed - have;
			if (subRecipe == null || subRecipe.ingredients == null || shortfall <= 0)
			{
				return false;
			}

			final int batches = subRecipe.batchesFor(shortfall);
			for (Recipe.Ingredient ingredient : subRecipe.ingredients)
			{
				int held = 0;
				for (int id : ingredient.allIds())
				{
					ItemCount count = counts.get(id);
					if (count != null)
					{
						held += count.total();
					}
				}

				if (held < ingredient.quantity * batches)
				{
					return false;
				}
			}
			return true;
		}

		private void refreshText()
		{
			count.setText(have + " / " + needed);
			count.setForeground(countColor);
		}
	}

	/**
	 * A material inside one recipe. Clicking it adds that material's own recipe
	 * as a sub-goal of whatever needs it, for the full amount that goal requires.
	 */
	private class IngredientRow extends MaterialRow
	{
		private final int perCraft;

		IngredientRow(Goal owner, Recipe.Ingredient ingredient)
		{
			super(ingredient);
			this.perCraft = ingredient.quantity;

			if (subRecipe != null)
			{
				makeRowClickable(this, () -> addSubGoal(owner, subRecipe.name, needed), true);
			}
		}
	}

	/** A line of the combined shopping list. Read-only: it belongs to no one goal. */
	private class SummaryRow extends MaterialRow
	{
		SummaryRow(Recipe.Ingredient ingredient)
		{
			super(ingredient);
		}
	}
}

package com.recipechecklist;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Recipe Checklist",
	description = "Build a checklist of items you want to make and track the materials you still need",
	tags = {"checklist", "materials", "crafting", "smithing", "skilling", "shopping"}
)
public class RecipeChecklistPlugin extends Plugin
{
	private static final String GOALS_KEY = "goals";
	private static final String SUMMARY_COLLAPSED_KEY = "summaryCollapsed";

	/** "Bronze cannon materials: Plank x 4, Bronze nails x 16, Bronze bar x 8." */
	private static final Pattern MATERIALS_MESSAGE = Pattern.compile("^(.+?) materials: (.+?)\\.?$");
	private static final Pattern MATERIAL_AMOUNT = Pattern.compile("x (\\d+)");

	/** Options that move around an interface rather than pick something out of it. */
	private static final Set<String> NAVIGATION_OPTIONS = ImmutableSet.of(
		"View", "Close", "Back", "Select", "Continue", "Scroll up", "Scroll down", "Check");

	/** Interfaces that list things you can make. */
	private static final Set<Integer> WATCHED_INTERFACES = ImmutableSet.of(
		InterfaceID.SKILL_GUIDE,
		InterfaceID.SKILL_GUIDE_V2,
		InterfaceID.POH_FURNITURE_CREATION,
		InterfaceID.POH_FURNITURE_CREATION_MENU,
		InterfaceID.SAILING_CUSTOMISATION,
		InterfaceID.SAILING_BOAT_SELECTION,
		InterfaceID.SAILING_BT_SELECTION,
		InterfaceID.SAILING_MENU);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private RecipeChecklistConfig config;

	@Inject
	private ScheduledExecutorService executor;

	private RecipeBook recipeBook;
	private RecipeChecklistPanel panel;
	private NavigationButton navButton;
	private BankMemory bankMemory;

	@Provides
	RecipeChecklistConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RecipeChecklistConfig.class);
	}

	@Override
	protected void startUp()
	{
		recipeBook = new RecipeBook(gson);
		bankMemory = new BankMemory(gson);
		panel = new RecipeChecklistPanel(this, itemManager, recipeBook);
		panel.restoreGoals(
			configManager.getConfiguration(RecipeChecklistConfig.GROUP, GOALS_KEY),
			Boolean.TRUE.equals(configManager.getConfiguration(
				RecipeChecklistConfig.GROUP, SUMMARY_COLLAPSED_KEY, Boolean.class)));

		// Already logged in when the plugin is switched on mid-session.
		loadBankMemory();

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Recipe Checklist")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		refresh();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);

		final BankMemory closing = bankMemory;
		if (closing != null)
		{
			executor.execute(closing::flush);
		}

		navButton = null;
		panel = null;
		recipeBook = null;
		bankMemory = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				loadBankMemory();
				break;

			// Save on the way out rather than on every bank change: moving items
			// around fires this constantly, and writing each time would be pointless
			// disk churn.
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				saveBankMemory();
				break;

			default:
				break;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		final int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			// The only moment the bank is actually readable, so take a copy.
			rememberBank(event.getItemContainer());
		}

		if (id == InventoryID.INV || id == InventoryID.BANK)
		{
			refresh();
		}
	}

	private void rememberBank(ItemContainer bank)
	{
		if (bankMemory != null && bank != null)
		{
			bankMemory.remember(tally(bank));
		}
	}

	private void loadBankMemory()
	{
		final BankMemory memory = bankMemory;
		final long accountHash = client.getAccountHash();
		if (memory == null || accountHash == -1)
		{
			return;
		}

		executor.execute(() ->
		{
			memory.load(accountHash);
			refresh();
		});
	}

	private void saveBankMemory()
	{
		final BankMemory memory = bankMemory;
		if (memory != null)
		{
			executor.execute(memory::flush);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RecipeChecklistConfig.GROUP.equals(event.getGroup()))
		{
			refresh();
		}
	}

	/**
	 * Adds a recipe to the checklist when you click one in a skill guide or the
	 * construction build menu.
	 * <p>
	 * This only observes clicks you already made - no menu entries are added,
	 * removed or reordered, and nothing extra is sent to the server.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!addingFromGame())
		{
			return;
		}

		final int component = event.getParam1();
		if (component <= 0 || !WATCHED_INTERFACES.contains(WidgetUtil.componentToInterface(component)))
		{
			return;
		}

		final Recipe recipe = resolveClicked(event, component);
		if (recipe == null)
		{
			// Navigating a skill guide fires a click per category and on the close
			// button; only log the misses that might be a naming mismatch worth fixing.
			if (!NAVIGATION_OPTIONS.contains(event.getMenuOption()))
			{
				log.debug("No recipe for click: interface={} component={} option={} target={} itemId={}",
					WidgetUtil.componentToInterface(component),
					WidgetUtil.componentToId(component),
					event.getMenuOption(),
					event.getMenuTarget(),
					event.getItemId());
			}
			return;
		}

		log.debug("Adding {} from in-game click", recipe.name);
		SwingUtilities.invokeLater(() -> panel.addGoal(recipe.name, 1));
	}

	/**
	 * These interfaces show a thing you can make, so a click on one is a
	 * statement of intent. Item id first when the widget carries one, otherwise
	 * the label you clicked.
	 */
	private Recipe resolveClicked(MenuOptionClicked event, int component)
	{
		// Skill guides put the item on the event ("Check materials" on a larder),
		// while other interfaces carry it on the widget. Try both before falling
		// back to reading the label.
		Recipe byEventItem = recipeFor(event.getItemId());
		if (byEventItem != null)
		{
			return byEventItem;
		}

		final Widget widget = client.getWidget(component);
		if (widget != null)
		{
			Recipe byWidgetItem = recipeFor(widget.getItemId());
			if (byWidgetItem != null)
			{
				return byWidgetItem;
			}
		}

		final String target = Text.removeTags(event.getMenuTarget()).trim();
		if (target.isEmpty())
		{
			return null;
		}

		// This product's own recipes only, never a loose search: the shipwright
		// reports "Upgrade" as the target, and searching that once matched every
		// part to "Teak cape rack (Upgrade - materials)".
		return recipeBook.bestFor(target);
	}

	private Recipe recipeFor(int itemId)
	{
		return itemId > 0 ? recipeBook.simplestFor(itemId) : null;
	}

	/**
	 * Whether a click in game should land on the checklist right now.
	 * <p>
	 * Requiring shift keeps ordinary building and browsing from filling the list
	 * up, without touching any menu - the alternative, adding an entry to the
	 * right-click menu, is exactly what the plugin rules forbid for Construction.
	 * Client thread only, since it reads the key state.
	 */
	private boolean addingFromGame()
	{
		if (panel == null || !config.addFromGameClicks())
		{
			return false;
		}
		return !config.requireShiftToAdd() || client.isKeyPressed(KeyCode.KC_SHIFT);
	}

	/**
	 * The shipwright announces what a part costs in the chat:
	 * "Bronze cannon materials: Plank x 4, Bronze nails x 16, Bronze bar x 8."
	 * <p>
	 * That line names the part far more reliably than the click does, so it is
	 * what we key on. Nothing is sent anywhere - we are reading a message the
	 * game already printed.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!addingFromGame() || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		final Matcher matcher = MATERIALS_MESSAGE.matcher(Text.removeTags(event.getMessage()));
		if (!matcher.matches())
		{
			return;
		}

		final Recipe recipe = matchPart(matcher.group(1).trim(), matcher.group(2));
		if (recipe == null)
		{
			log.debug("No recipe for shipwright part: {}", matcher.group(1));
			return;
		}

		log.debug("Adding {} from shipwright materials message", recipe.name);
		SwingUtilities.invokeLater(() -> panel.addGoal(recipe.name, 1));
	}

	/**
	 * Find the recipe a materials message describes.
	 * <p>
	 * Where a part has per-hull variants the name alone is ambiguous, so the
	 * quantities in the message pick between them. Anything still ambiguous is
	 * left alone rather than guessed at.
	 */
	private Recipe matchPart(String partName, String materials)
	{
		final Recipe exact = recipeBook.get(partName);
		if (exact != null)
		{
			return exact;
		}

		final List<Integer> quantities = new ArrayList<>();
		final Matcher amounts = MATERIAL_AMOUNT.matcher(materials);
		while (amounts.find())
		{
			quantities.add(Integer.parseInt(amounts.group(1)));
		}
		Collections.sort(quantities);

		Recipe matched = null;
		for (Recipe candidate : recipeBook.variantsOf(partName))
		{
			final List<Integer> candidateQuantities = new ArrayList<>();
			for (Recipe.Ingredient ingredient : candidate.ingredients)
			{
				candidateQuantities.add(ingredient.quantity);
			}
			Collections.sort(candidateQuantities);

			if (candidateQuantities.equals(quantities))
			{
				if (matched != null)
				{
					return null;
				}
				matched = candidate;
			}
		}
		return matched;
	}

	/**
	 * Counts and item names both have to be read on the client thread, so gather
	 * them there and hand the results back to the panel on the EDT.
	 */
	void refresh()
	{
		if (panel == null)
		{
			return;
		}

		final Set<Integer> wanted = panel.trackedItemIds();
		if (wanted.isEmpty())
		{
			return;
		}

		final BankMemory memory = bankMemory;
		final boolean countBank = config.includeBank() && memory != null;

		clientThread.invoke(() ->
		{
			final Map<Integer, Integer> inventory = tally(client.getItemContainer(InventoryID.INV));

			final Map<Integer, ItemCount> counts = new HashMap<>();
			for (int itemId : wanted)
			{
				counts.put(itemId, new ItemCount(
					inventory.getOrDefault(itemId, 0),
					countBank ? memory.count(itemId) : 0,
					itemManager.getItemComposition(itemId).getName()));
			}

			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.applyCounts(counts);
				}
			});
		});
	}

	/**
	 * Total everything in a container, keyed by canonical item id.
	 * <p>
	 * Counting ids directly misses anything held in another form: a noted plank
	 * has its own item id, so someone carrying 100 noted oak planks would have
	 * read as having none. Canonicalising folds notes and bank placeholders back
	 * onto the item they stand for, using the game's own mapping rather than a
	 * guess about which ids are equivalent. Client thread only.
	 */
	private Map<Integer, Integer> tally(ItemContainer container)
	{
		if (container == null)
		{
			return Collections.emptyMap();
		}

		final Map<Integer, Integer> totals = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getQuantity() > 0)
			{
				totals.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return totals;
	}

	void persistGoals(String serialized)
	{
		configManager.setConfiguration(RecipeChecklistConfig.GROUP, GOALS_KEY, serialized);
	}

	void persistSummaryCollapsed(boolean collapsed)
	{
		configManager.setConfiguration(RecipeChecklistConfig.GROUP, SUMMARY_COLLAPSED_KEY, collapsed);
	}
}

